import { createHash, createPublicKey, randomBytes, verify } from "node:crypto";
import {
  accessSync,
  chmodSync,
  constants,
  mkdirSync,
  readFileSync,
  renameSync,
  statSync,
  unlinkSync,
} from "node:fs";
import { open } from "node:fs/promises";
import { homedir } from "node:os";
import { delimiter, extname, isAbsolute, join } from "node:path";

import {
  BINARY_RELEASE,
  BINARY_RELEASE_BASE_DEFAULT,
  BINARY_SIGNING_PUBKEY,
} from "./release.generated.mjs";

function executable(path) {
  try {
    if (process.platform !== "win32") accessSync(path, constants.X_OK);
    return statSync(path).isFile();
  } catch {
    return false;
  }
}

export function executableCandidateNames(
  name,
  platform = process.platform,
  pathExt = process.env.PATHEXT ?? ".COM;.EXE;.BAT;.CMD",
) {
  if (platform !== "win32" || extname(name)) return [name];
  const candidates = [];
  for (const extension of pathExt.split(";").map((value) => value.trim()).filter(Boolean)) {
    candidates.push(`${name}${extension.startsWith(".") ? extension : `.${extension}`}`);
  }
  // npm installs a POSIX shim beside its native .CMD shim. Windows X_OK is
  // existence-only, so native PATHEXT candidates must win before bare fallback.
  candidates.push(name);
  const seen = new Set();
  return candidates.filter((candidate) => {
    const key = candidate.toLowerCase();
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function onPath(name) {
  if (isAbsolute(name) || /[\\/]/.test(name)) return executable(name) ? name : null;
  for (const dir of (process.env.PATH ?? "").split(delimiter)) {
    if (!dir) continue;
    for (const candidate of executableCandidateNames(name)) {
      const path = join(dir, candidate);
      if (executable(path)) return path;
    }
  }
  return null;
}

export function targetPlatform(os = process.platform, nodeArch = process.arch) {
  const arch = nodeArch === "x64" ? "amd64" : nodeArch;
  if (!(os === "darwin" || os === "linux" || os === "win32") ||
      !(arch === "arm64" || arch === "amd64")) {
    throw new Error(`no prebuilt binary for ${os}/${arch} — supported: darwin/arm64, darwin/amd64, linux/arm64, linux/amd64, win32/arm64, win32/amd64`);
  }
  return { os, arch };
}

export function binaryInstallFilename(name, os = process.platform) {
  return os === "win32" ? `${name}.exe` : name;
}

function timeoutMs() {
  const raw = process.env.CAVE_SETUP_TIMEOUT ?? "300";
  const seconds = Number(raw);
  if (!Number.isInteger(seconds) || seconds <= 0) {
    throw new Error(`CAVE_SETUP_TIMEOUT must be a positive integer (got ${JSON.stringify(raw)})`);
  }
  return seconds * 1000;
}

async function asset(url, timeout) {
  let response;
  try {
    response = await fetch(url, { signal: AbortSignal.timeout(timeout) });
  } catch (error) {
    throw new Error(`binary download failed: ${error.message}`);
  }
  if (!response.ok) throw new Error(`binary download failed: HTTP ${response.status}`);
  return response;
}

function signedDigest(checksums, bundleRaw) {
  try {
    const bundle = JSON.parse(bundleRaw);
    if (bundle.mediaType !== "application/vnd.dev.sigstore.bundle.v0.3+json") return false;
    if (bundle.messageSignature?.messageDigest?.algorithm !== "SHA2_256") return false;
    const digest = createHash("sha256").update(checksums).digest();
    const bundled = Buffer.from(bundle.messageSignature.messageDigest.digest, "base64");
    if (digest.length !== bundled.length || !digest.equals(bundled)) return false;
    return verify(
      "sha256",
      Buffer.from(checksums),
      createPublicKey(BINARY_SIGNING_PUBKEY),
      Buffer.from(bundle.messageSignature.signature, "base64"),
    );
  } catch {
    return false;
  }
}

function expectedDigest(checksums, artifact) {
  for (const line of checksums.split("\n")) {
    if (!line) continue;
    const match = line.match(/^([a-f0-9]{64})  ([A-Za-z0-9._-]+)$/);
    if (!match) throw new Error("signed checksum manifest is malformed");
    if (match[2] === artifact) return match[1];
  }
  throw new Error(`signed checksum manifest does not contain ${artifact}`);
}

function cleanup(path) {
  try {
    unlinkSync(path);
  } catch (error) {
    if (error.code !== "ENOENT") throw error;
  }
}

async function download(url, part, timeout) {
  const response = await asset(url, timeout);
  if (!response.body) throw new Error("binary download failed: response body missing");
  const hash = createHash("sha256");
  const file = await open(part, constants.O_CREAT | constants.O_EXCL | constants.O_WRONLY, 0o600);
  const reader = response.body.getReader();
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      hash.update(value);
      await file.write(value);
    }
  } finally {
    reader.releaseLock();
    await file.close();
  }
  return hash.digest("hex");
}

// Windows refuses to replace a file another process holds open, and the
// binaries this installs (caveman-proxy, cavemem) are long-lived daemons — an
// update issued while one is running failed the rename outright and then the
// catch deleted the verified download, so the user was left with neither the
// new binary nor a retry (#657). Back off and try again; the daemon usually
// exits within a second or two of being asked to.
async function replaceWithRetry(part, target, attempts = 6) {
  for (let attempt = 0; ; attempt++) {
    try {
      renameSync(part, target);
      return;
    } catch (error) {
      const locked = error.code === "EPERM" || error.code === "EBUSY" ||
                     error.code === "EACCES" || error.code === "ETXTBSY";
      if (!locked || attempt >= attempts - 1) throw error;
      await new Promise((done) => setTimeout(done, 100 * 2 ** attempt));
    }
  }
}

export async function ensureBinary({ name, envVar }) {
  const explicit = process.env[envVar];
  if (explicit) {
    if (!executable(explicit)) throw new Error(`${envVar} does not point to an executable: ${explicit}`);
    return explicit;
  }
  const found = onPath(name);
  if (found) return found;
  const binDir = join(process.env.CAVEMAN_HOME ?? join(homedir(), ".caveman"), "bin");
  const target = join(binDir, binaryInstallFilename(name));
  if (executable(target)) return target;

  const { os, arch } = targetPlatform();
  const artifact = `${name}_${os}_${arch}`;
  const base = (process.env.CAVE_BINARY_RELEASE_BASE ?? BINARY_RELEASE_BASE_DEFAULT).replace(/\/+$/, "");
  const release = `${base}/${BINARY_RELEASE}`;
  const timeout = timeoutMs();
  const [checksumsResponse, signatureResponse] = await Promise.all([
    asset(`${release}/checksums.txt`, timeout),
    asset(`${release}/checksums.txt.keysig`, timeout),
  ]);
  const [checksums, signature] = await Promise.all([checksumsResponse.text(), signatureResponse.text()]);
  if (!signedDigest(checksums, signature)) {
    throw new Error("signature check failed for checksums.txt — refusing to install");
  }
  const expected = expectedDigest(checksums, artifact);
  mkdirSync(binDir, { recursive: true });
  // Per-process part path, and NO pre-unlink. A fixed `${target}.part` plus a
  // cleanup() immediately before an O_CREAT|O_EXCL open made the exclusivity
  // guard unreachable: two concurrent installs (npx -y caveman-mcp is registered
  // per MCP session, so several agents can start one at once) raced — B unlinked
  // A's directory entry and created its own inode, A hashed ITS OWN bytes and
  // matched, and then the PATH-based chmod+rename published B's half-written file
  // as "checksum verified". Both the chmod and the rename now act on a name only
  // this process can own.
  //
  // ponytail: a SIGKILL mid-download now leaves one stray .part behind instead of
  // reusing the fixed name. Sweep binDir for stale .part files if that ever shows
  // up in the wild.
  const part = `${target}.${process.pid}.${randomBytes(6).toString("hex")}.part`;
  try {
    const actual = await download(`${release}/${artifact}`, part, timeout);
    if (actual !== expected) throw new Error(`signature check failed for ${artifact} — partial download deleted`);
    chmodSync(part, 0o755);
    await replaceWithRetry(part, target);
  } catch (error) {
    cleanup(part);
    throw error;
  }
  process.stderr.write(`${name}  ${os}/${arch}  checksum verified\n`);
  return target;
}

#!/usr/bin/env node
// Launcher for the caveman-mcp server. The server itself is the prebuilt Go
// `caveman-mcp` binary (it links the engine in-process); this shim only locates
// and execs it, forwarding stdio so the MCP host talks to the binary directly.
//
import { spawn } from "node:child_process";
import { existsSync, realpathSync } from "node:fs";
import { basename, delimiter, dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { ensureBinary } from "./binary-installer.generated.mjs";

let bin;
const launcher = realpathSync(fileURLToPath(import.meta.url));
const explicit = process.env.CAVEMAN_MCP_BIN;
if (explicit && existsSync(explicit) && realpathSync(explicit) === launcher) {
  process.stderr.write(`caveman-mcp: CAVEMAN_MCP_BIN must point to the Go binary, not the npm launcher\n`);
  process.exit(127);
}
const originalPath = process.env.PATH;
process.env.PATH = withoutOwnNpmBin(originalPath);
try {
  bin = await ensureBinary({ name: "caveman-mcp", envVar: "CAVEMAN_MCP_BIN" });
} catch (error) {
  process.stderr.write(`caveman-mcp: ${error.message}\n`);
  process.exit(127);
} finally {
  if (originalPath === undefined) delete process.env.PATH;
  else process.env.PATH = originalPath;
}
const child = spawn(bin, process.argv.slice(2), { stdio: "inherit" });

function withoutOwnNpmBin(value = "") {
  return value.split(delimiter).filter((directory) => {
    if (!directory) return false;
    const absolute = resolve(directory);
    if (basename(absolute).toLowerCase() === ".bin" &&
        basename(dirname(absolute)).toLowerCase() === "node_modules") return false;
    try {
      return realpathSync(resolve(absolute, "caveman-mcp")) !== launcher;
    } catch {
      return true;
    }
  }).join(delimiter);
}

child.on("error", (err) => {
  if (err.code === "ENOENT") {
    process.stderr.write(`caveman-mcp: verified binary disappeared before launch (${bin})\n`);
    process.exit(127);
  }
  process.stderr.write(`caveman-mcp: ${err.message}\n`);
  process.exit(1);
});

child.on("exit", (code, signal) => {
  if (signal) process.kill(process.pid, signal);
  else process.exit(code ?? 0);
});

// Generated by packages/cli/scripts/gen-wedge-installer.mjs. Do not edit.
export const BINARY_RELEASE = "bin-v1.1.5";
export const BINARY_RELEASE_BASE_DEFAULT = "https://github.com/JuliusBrussee/caveman/releases/download";
export const BINARY_SIGNING_PUBKEY = "-----BEGIN PUBLIC KEY-----\nMFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAEKR5zq0dz0mTUtkiX0b6jqtyG3uQV\n89PGD2n9UBV1ikbhu0f1c+vHtcN9mk6wKzyBLdEPudI/Jnvci+8OAen/vw==\n-----END PUBLIC KEY-----\n";

// Command caveman-mcp is the Caveman MCP server over stdio. An MCP host (Claude
// Code, Cursor, …) spawns it and speaks JSON-RPC on stdin/stdout; the three
// caveman_* tools wrap the Caveman Engine. Logs go to stderr only — stdout
// is the protocol channel.
//
// By default it opens the SHARED file recovery store (CAVEMAN_CCR_DB, else
// ~/.caveman/ccr.db) — the same store the Caveman gateway writes — so a
// caveman_retrieve here resolves handles the proxy disclosed (this is what lets a
// wrapped agent recover proxy-elided detail on streaming requests). Set
// CAVEMAN_MCP_EPHEMERAL=1 for a fresh in-memory store that touches no disk.
package main

import (
	"encoding/json"
	"io"
	"log/slog"
	"os"
	"path/filepath"

	"github.com/JuliusBrussee/caveman/engine"
	"github.com/JuliusBrussee/caveman/engine/ccr"
	"github.com/JuliusBrussee/caveman/mcp"
)

var version = "dev"

func main() {
	if handled, code := handleArgs(os.Args[1:], os.Stdout, os.Stderr); handled {
		os.Exit(code)
	}
	logger := slog.New(slog.NewTextHandler(os.Stderr, &slog.HandlerOptions{Level: slog.LevelInfo}))

	store, err := openRecoveryStore()
	if err != nil {
		logger.Error("open recovery store", "err", err)
		os.Exit(1)
	}
	defer store.Close()

	eng := engine.New(store, nil)
	srv := mcp.NewServerVersion("caveman", version, mcp.EngineTools(eng, logger), logger)
	if err := srv.Serve(os.Stdin, os.Stdout); err != nil {
		logger.Error("serve", "err", err)
		os.Exit(1)
	}
}

func handleArgs(args []string, stdout, stderr io.Writer) (bool, int) {
	if len(args) == 0 {
		return false, 0
	}
	if len(args) == 2 && args[0] == "version" && args[1] == "--json" {
		err := json.NewEncoder(stdout).Encode(map[string]any{
			"version":      version,
			"schema":       "caveman.mcp.version.v1",
			"capabilities": []string{"mcp_recovery", "build_stamped_version"},
		})
		if err != nil {
			return true, 1
		}
		return true, 0
	}
	_, _ = io.WriteString(stderr, "usage: caveman-mcp [version --json]\n")
	return true, 2
}

// openRecoveryStore opens the shared file CCR store the proxy uses, so handles are
// resolvable across processes. CAVEMAN_MCP_EPHEMERAL=1 forces an in-memory store
// (no disk). The path mirrors the proxy: CAVEMAN_CCR_DB, else ~/.caveman/ccr.db.
func openRecoveryStore() (*ccr.Store, error) {
	if os.Getenv("CAVEMAN_MCP_EPHEMERAL") == "1" {
		return ccr.OpenMemory()
	}
	path := os.Getenv("CAVEMAN_CCR_DB")
	if path == "" {
		home := os.Getenv("CAVEMAN_HOME")
		if home == "" {
			h, err := os.UserHomeDir()
			if err != nil {
				return ccr.OpenMemory()
			}
			home = filepath.Join(h, ".caveman")
		}
		path = filepath.Join(home, "ccr.db")
	}
	return ccr.Open(path)
}

package main

import (
	"bytes"
	"encoding/json"
	"testing"
)

func TestVersionJSON(t *testing.T) {
	var stdout bytes.Buffer
	var stderr bytes.Buffer
	handled, code := handleArgs([]string{"version", "--json"}, &stdout, &stderr)
	if !handled || code != 0 {
		t.Fatalf("handled=%v code=%d stderr=%q", handled, code, stderr.String())
	}
	var got struct {
		Version      string   `json:"version"`
		Schema       string   `json:"schema"`
		Capabilities []string `json:"capabilities"`
	}
	if err := json.Unmarshal(stdout.Bytes(), &got); err != nil {
		t.Fatalf("decode output: %v", err)
	}
	if got.Version != version {
		t.Fatalf("version=%q want %q", got.Version, version)
	}
	if got.Schema != "caveman.mcp.version.v1" {
		t.Fatalf("schema=%q", got.Schema)
	}
	if len(got.Capabilities) != 2 || got.Capabilities[0] != "mcp_recovery" {
		t.Fatalf("capabilities=%v", got.Capabilities)
	}
}

func TestUnknownArgumentExitsTwo(t *testing.T) {
	var stdout bytes.Buffer
	var stderr bytes.Buffer
	handled, code := handleArgs([]string{"unknown"}, &stdout, &stderr)
	if !handled || code != 2 {
		t.Fatalf("handled=%v code=%d", handled, code)
	}
	if stdout.Len() != 0 {
		t.Fatalf("stdout=%q", stdout.String())
	}
	if stderr.String() != "usage: caveman-mcp [version --json]\n" {
		t.Fatalf("stderr=%q", stderr.String())
	}
}

func TestNoArgumentsStartsServer(t *testing.T) {
	handled, code := handleArgs(nil, &bytes.Buffer{}, &bytes.Buffer{})
	if handled || code != 0 {
		t.Fatalf("handled=%v code=%d", handled, code)
	}
}

package mcp

import (
	"encoding/json"
	"log/slog"
	"strings"
	"sync"

	"github.com/JuliusBrussee/caveman/engine"
	"github.com/JuliusBrussee/caveman/engine/ccr"
)

// Engine is the slice of the Caveman Engine the Caveman tools need.
// *engine.Engine satisfies it; tests inject a mock so the framing can be proven
// without the real compressors.
type Engine interface {
	Compress(input []byte, opts engine.Options) (engine.Result, error)
	Retrieve(handle string) ([]byte, error)
	RetrieveQuery(handle, query string) ([]byte, error)
	Stats() (ccr.Stats, error)
	EncodeTOON(input []byte) ([]byte, error)
	DecodeTOON(input []byte) ([]byte, error)
}

// Tool names — exactly these five, case-sensitive, are exposed (PRD §11.1;
// the TOON pair is the wrap-simplification spec's agent-facing encoder).
const (
	ToolCompress   = "caveman_compress"
	ToolRetrieve   = "caveman_retrieve"
	ToolStats      = "caveman_stats"
	ToolToonEncode = "caveman_toon_encode"
	ToolToonDecode = "caveman_toon_decode"
)

// EngineTools returns the five Caveman compression tools bound to eng. log may
// be nil. This is the tool set the caveman-mcp binary serves.
func EngineTools(eng Engine, log *slog.Logger) []Tool {
	if log == nil {
		log = slog.New(slog.NewTextHandler(discard{}, nil))
	}
	// One server process is one session, so the recovery ledger lives for exactly
	// as long as the conversation whose retrieves it is counting.
	recoveries := newRetrieveSession()
	return []Tool{
		{
			Name:        ToolCompress,
			Description: "Compress a large text or tool-output payload before it enters the model context. Lossy (S4) but reversible: returns the compressed text, an inferred token ratio, and a recovery_handle for caveman_retrieve. Fails closed: unusable input or a result that is not smaller returns unchanged with ratio 0.",
			InputSchema: ObjectSchema(map[string]any{
				"input":        StringProp("The payload to compress."),
				"content_type": StringProp("Optional engine content type, e.g. json or toon."),
				"type":         StringProp("Alias for content_type."),
			}, "input"),
			Handler: func(args json.RawMessage) ToolResult { return compressTool(eng, log, args) },
		},
		{
			Name:        ToolRetrieve,
			Description: "Recover content that a previous caveman_compress (or the Caveman Engine) dropped. LAST RESORT, not a paging API. An elision marker states facts computed from the exact units it replaced (\"… 340 rows elided (caveman): all state=charged; range amount=5.00..199.99 …\"), and every dropped unit resembles one still shown — so counts, totals, and per-field questions are usually answerable from the visible view plus those invariants, with no call at all. Retrieve only for exact bytes you cannot derive that way, and then make ONE call per handle with a broad query covering everything you need; a sequence of narrow per-row retrievals re-reads the whole conversation prefix each time and costs far more than the compression saved. Pass the exact recovery_handle beginning ccr_; full <<ccr:...>> markers and ccr:ccr_ prefixes are normalized. Unknown handles fail explicitly. A query-narrowed view returns COMPLETE records only — never a plucked line — and prints \"… [caveman: non-adjacent] …\" wherever content was skipped, including at the start and end: records on either side of that marker are NOT consecutive and nothing may be inferred from their order or from what is missing between them.",
			InputSchema: ObjectSchema(map[string]any{
				"recovery_handle": StringProp("Exact ccr_ handle returned by Caveman or copied from a <<ccr:HANDLE>> marker."),
				"query":           StringProp("Optional but strongly preferred: one broad description covering every detail you need from this handle, so a single call answers the whole question instead of many narrow ones."),
			}, "recovery_handle"),
			// Recovery returns the exact original bytes: exempt from the
			// result-size cap so a >cap original (the shared gateway store has no
			// matching ceiling) stays recoverable rather than failing closed on
			// size (#139).
			ExemptResultCap: true,
			Handler:         func(args json.RawMessage) ToolResult { return retrieveTool(eng, recoveries, args) },
		},
		{
			Name:        ToolStats,
			Description: "Report this session's aggregate compression: tokens before/after, request count, and an inferred ratio. Local-only; never a verified figure.",
			InputSchema: ObjectSchema(map[string]any{}),
			Handler:     func(json.RawMessage) ToolResult { return statsTool(eng) },
		},
		{
			Name:        ToolToonEncode,
			Description: "Re-encode uniform/tabular JSON as TOON before quoting it into context — smaller for arrays of same-shaped objects. Lossless data re-encoding with JSON round-trip; input that cannot round-trip is returned unchanged with a note saying why. Returns both sizes so you can decide.",
			InputSchema: ObjectSchema(map[string]any{
				"input": StringProp("The JSON to re-encode as TOON."),
			}, "input"),
			Handler: func(args json.RawMessage) ToolResult { return toonEncodeTool(eng, log, args) },
		},
		{
			Name:        ToolToonDecode,
			Description: "Decode TOON back into JSON. Fails loudly on input that is not valid TOON — it never emits the raw input as if it were JSON.",
			InputSchema: ObjectSchema(map[string]any{
				"input": StringProp("The TOON to decode back into JSON."),
			}, "input"),
			Handler: func(args json.RawMessage) ToolResult { return toonDecodeTool(eng, args) },
		},
	}
}

type compressPayload struct {
	Compressed      string  `json:"compressed"`
	Ratio           float64 `json:"ratio"`
	TokensBefore    int     `json:"tokens_before"`
	TokensAfter     int     `json:"tokens_after"`
	Basis           string  `json:"basis"`
	ContentType     string  `json:"content_type"`
	RecoveryHandle  *string `json:"recovery_handle"`
	Method          string  `json:"method,omitempty"`
	LosslessToModel *bool   `json:"lossless_to_model,omitempty"`
}

type statsPayload struct {
	TokensBefore int     `json:"tokens_before"`
	TokensAfter  int     `json:"tokens_after"`
	Requests     int     `json:"requests"`
	Ratio        float64 `json:"ratio"`
	Basis        string  `json:"basis"`
	Scope        string  `json:"scope"`
}

// compressTool compresses the input string. Fail-closed: malformed,
// incompressible, or not-smaller input returns the original with ratio 0 and a
// null handle — a pass-through, never an error (PRD §11.3).
func compressTool(eng Engine, log *slog.Logger, args json.RawMessage) ToolResult {
	var a struct {
		Input       string `json:"input"`
		ContentType string `json:"content_type"`
		Type        string `json:"type"`
	}
	if err := json.Unmarshal(args, &a); err != nil {
		return ToolError("cave_invalid_arguments", "compress: invalid arguments")
	}
	contentType := a.ContentType
	if contentType == "" {
		contentType = a.Type
	}
	res, err := eng.Compress([]byte(a.Input), engine.Options{Mode: engine.ModeCompress, Type: contentType})
	if err != nil {
		log.Warn("compress fell back to pass-through", "err", err)
		// Engine returns a fully-accounted byte-exact pass-through when recovery
		// persistence fails. Preserve it. A third-party Engine implementation that
		// returns an unsafe/empty result with an error fails loudly instead of
		// making non-empty content appear to cost zero tokens.
		if string(res.Output) != a.Input || res.TokensAfter != res.TokensBefore || (a.Input != "" && res.TokensBefore <= 0) || res.RecoveryHandle != "" {
			return ToolError("cave_compress_failed", "compress: recovery persistence failed")
		}
	}
	return ToolText(compressResultPayload(res))
}

func compressResultPayload(res engine.Result) compressPayload {
	var handle *string
	if res.RecoveryHandle != "" {
		h := res.RecoveryHandle
		handle = &h
	}
	return compressPayload{
		Compressed:      string(res.Output),
		Ratio:           res.Ratio,
		TokensBefore:    res.TokensBefore,
		TokensAfter:     res.TokensAfter,
		Basis:           res.Basis,
		ContentType:     res.ContentType,
		RecoveryHandle:  handle,
		Method:          res.Method,
		LosslessToModel: res.LosslessToModel,
	}
}

// retrieveTool returns the exact original for a handle; an unknown handle is a
// fail-closed tool error carrying a cave_snake_code (PRD §11.4). session may be
// nil, in which case every retrieve behaves exactly as it did before the
// anti-storm ledger existed.
func retrieveTool(eng Engine, session *retrieveSession, args json.RawMessage) ToolResult {
	var a struct {
		RecoveryHandle string `json:"recovery_handle"`
		Query          string `json:"query"`
	}
	if err := json.Unmarshal(args, &a); err != nil || a.RecoveryHandle == "" {
		return ToolError("cave_invalid_arguments", "retrieve: missing recovery_handle")
	}
	a.RecoveryHandle = normalizeRecoveryHandle(a.RecoveryHandle)
	if a.RecoveryHandle == "" {
		return ToolError("cave_invalid_arguments", "retrieve: missing recovery_handle")
	}
	// Already answered verbatim in this session: the bytes are above in the
	// transcript, so re-sending them buys nothing and costs a turn. Only ever said
	// of a request already served — never of content this session has not seen.
	if session.alreadyServed(a.RecoveryHandle, a.Query) {
		return ToolRawText(repeatNote)
	}
	// Past the historical storm threshold, stop paging. This policy intends to
	// avoid later narrow-query turns; no paired counterfactual has validated the
	// threshold or a token saving.
	if session.shouldPayOutInFull() {
		original, err := eng.RetrieveQuery(a.RecoveryHandle, "")
		if err != nil {
			return ToolError("cave_unknown_handle", "no original found for handle")
		}
		session.record(a.RecoveryHandle, a.Query)
		session.record(a.RecoveryHandle, "")
		return ToolRawText(fullPayoutNote + "\n\n" + string(original))
	}
	// A query narrows recovery to the relevant sections (BM25); empty query is
	// byte-exact full recovery. RetrieveQuery never drops detail it cannot rank.
	original, err := eng.RetrieveQuery(a.RecoveryHandle, a.Query)
	if err != nil {
		return ToolError("cave_unknown_handle", "no original found for handle")
	}
	session.record(a.RecoveryHandle, a.Query)
	return ToolRawText(string(original))
}

// normalizeRecoveryHandle accepts every form of a recovery reference this stack
// has ever shown an agent, because an agent copies what it sees and a form that
// does not resolve turns one recovery into a storm.
//
//   - `ccr_…` — the bare handle Compress returns.
//   - `<<ccr:ccr_…>>` — the marker embedded in compressed content.
//   - `ccr:ccr_…` — the same, half-stripped.
//   - `ccr://…` — the native runtime's tool-output mask (`full: ccr://<id>`),
//     whose id is a typed OBJECT id rather than a blob handle. Engine.Retrieve
//     resolves both id spaces; this only has to hand it the id. Missing this form
//     is what made inventory-mismatch and webhook-delivery-gaps unanswerable on
//     2026-08-08 — the agent was shown a reference the recovery tool rejected.
func normalizeRecoveryHandle(handle string) string {
	handle = strings.TrimSpace(handle)
	if strings.HasPrefix(handle, "<<") && strings.HasSuffix(handle, ">>") {
		handle = strings.TrimSuffix(strings.TrimPrefix(handle, "<<"), ">>")
		handle = strings.TrimSpace(handle)
	}
	if rest, ok := strings.CutPrefix(handle, "ccr://"); ok {
		return strings.Trim(strings.TrimSpace(rest), "/")
	}
	if rest, ok := strings.CutPrefix(handle, "ccr:"); ok {
		return strings.TrimSpace(rest)
	}
	return handle
}

type toonEncodePayload struct {
	Output      string `json:"output"`
	Encoded     bool   `json:"encoded"`
	InputBytes  int    `json:"input_bytes"`
	OutputBytes int    `json:"output_bytes"`
	Note        string `json:"note,omitempty"`
}

// toonEncodeTool re-encodes JSON as TOON on explicit agent request. This is
// not the proxy's best-of gate: a valid encoding is returned even when it is
// not smaller (both sizes included), because the agent asked for it and can
// decide. Lossless round-trip: un-encodable input comes back unchanged with a
// note — never a silent no-op, never an invented encoding.
func toonEncodeTool(eng Engine, log *slog.Logger, args json.RawMessage) ToolResult {
	var a struct {
		Input string `json:"input"`
	}
	if err := json.Unmarshal(args, &a); err != nil || a.Input == "" {
		return ToolError("cave_invalid_arguments", "toon_encode: missing input")
	}
	out, err := eng.EncodeTOON([]byte(a.Input))
	if err != nil {
		log.Warn("toon encode fell back to pass-through", "err", err)
		return ToolText(toonEncodePayload{
			Output:      a.Input,
			Encoded:     false,
			InputBytes:  len(a.Input),
			OutputBytes: len(a.Input),
			Note:        "not encoded: " + err.Error(),
		})
	}
	return ToolText(toonEncodePayload{
		Output:      string(out),
		Encoded:     true,
		InputBytes:  len(a.Input),
		OutputBytes: len(out),
	})
}

// toonDecodeTool decodes TOON back to JSON. It fails loudly: invalid TOON is
// a tool error, never the raw input passed off as JSON (the same invariant as
// the CLI decode verb).
func toonDecodeTool(eng Engine, args json.RawMessage) ToolResult {
	var a struct {
		Input string `json:"input"`
	}
	if err := json.Unmarshal(args, &a); err != nil || a.Input == "" {
		return ToolError("cave_invalid_arguments", "toon_decode: missing input")
	}
	out, err := eng.DecodeTOON([]byte(a.Input))
	if err != nil {
		return ToolError("cave_invalid_toon", "toon_decode: input is not valid TOON; no JSON emitted")
	}
	return ToolRawText(string(out))
}

// statsTool returns session-scoped aggregate accounting, labeled inferred. The
// string "verified" never appears (PRD §11.5).
func statsTool(eng Engine) ToolResult {
	st, err := eng.Stats()
	if err != nil {
		return ToolError("cave_stats_unavailable", "stats unavailable")
	}
	return ToolText(statsPayload{
		TokensBefore: st.Totals.TokensBefore,
		TokensAfter:  st.Totals.TokensAfter,
		Requests:     st.Totals.Count,
		Ratio:        st.Totals.Ratio,
		Basis:        engine.BasisInferred,
		Scope:        "session",
	})
}

// discard is an io.Writer that drops everything (for a nil logger default).
type discard struct{}

func (discard) Write(p []byte) (int, error) { return len(p), nil }

// --- retrieve anti-storm ---
//
// Recovery is meant to be a last resort, and each call costs a whole agent turn:
// the model re-reads the entire conversation prefix, and everything a previous
// retrieve returned is part of that prefix from then on. So N retrieves do not
// cost N payloads, they cost N turns over a transcript that each one grew.
//
// A 2026-08-10 read-only sweep of 229 local CaveBench stdout files found 34
// sessions with 534 recovery tool calls: 3 sessions had one, 16 had 2-5, and
// 15 had more than 5 (p95 118, max 143). Eight of those 15 high-call sessions
// still passed their exact task grader. Only 3 of 534 normalized (handle,
// trimmed-query) pairs were exact repeats, so repeat suppression had little
// historical applicability; many calls used new handles or pointer chains.
// These are confounded arms, tasks, and repeated benchmark batches, not a paired
// intervention or the managed gateway's tool-result population. They describe
// recovery shape but do not validate a universal threshold or token saving.
//
// Two rules, neither of which may ever withhold something this session has not
// already been given:
//
//  1. An identical (handle, query) is answered with a pointer to the answer
//     already in the transcript. The bytes are verbatim above; sending them twice
//     is pure cost.
//  2. Past retrieveStormThreshold distinct retrieves, the next one returns the
//     handle's FULL stored original instead of a query-narrowed view, and says so.
//     This intends to avoid a longer sequence of narrow views by leaving nothing
//     to page for; the confounded corpus above does not prove a token or outcome
//     improvement from the rule.

// retrieveStormThreshold is how many distinct retrieves a session may make before
// the next one is paid out in full. Five is preserved as historical runtime
// behavior. The larger sweep above supersedes the incomplete 11/25/46 prior:
// more-than-five-call sessions can still pass, and no same-task paired run has
// isolated this intervention. Changing the threshold requires that experiment;
// these descriptive counts authorize neither tightening nor removal.
const retrieveStormThreshold = 5

const repeatNote = "… caveman: this exact recovery_handle and query were already answered earlier in this session — the content is verbatim above in this conversation. Re-read it there; issuing the same query again returns nothing new."

const fullPayoutNote = "… caveman: this session has now made several recoveries, so here is the COMPLETE stored original for this handle rather than a query-narrowed view. Everything recoverable for this handle is below — read it once and answer from it; further queries against it cannot return anything this does not already contain."

// retrieveSession is a session's recovery ledger. A nil *retrieveSession is safe
// to use and disables both behaviours, so any caller that has no session concept
// keeps the old semantics.
type retrieveSession struct {
	mu     sync.Mutex
	served map[string]bool
}

func newRetrieveSession() *retrieveSession {
	return &retrieveSession{served: map[string]bool{}}
}

// retrieveKey pairs a handle with a query. The query is compared after the same
// trimming RetrieveQuery applies, so "  " and "" are one request, not two.
func retrieveKey(handle, query string) string {
	return handle + "\x00" + strings.TrimSpace(query)
}

func (s *retrieveSession) alreadyServed(handle, query string) bool {
	if s == nil {
		return false
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.served[retrieveKey(handle, query)]
}

func (s *retrieveSession) shouldPayOutInFull() bool {
	if s == nil {
		return false
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	return len(s.served) >= retrieveStormThreshold
}

func (s *retrieveSession) record(handle, query string) {
	if s == nil {
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	s.served[retrieveKey(handle, query)] = true
}

package mcp

import (
	"encoding/json"
	"fmt"
	"strings"
	"testing"

	"github.com/JuliusBrussee/caveman/engine"
	"github.com/JuliusBrussee/caveman/engine/ccr"
)

// storeEngine is the slice of Engine the retrieve path needs, backed by a map of
// stored originals so the anti-storm rules can be exercised without a real store.
type storeEngine struct {
	originals map[string]string
	fullCalls int
	narrowed  int
}

func (e *storeEngine) Compress([]byte, engine.Options) (engine.Result, error) {
	return engine.Result{}, nil
}
func (e *storeEngine) Retrieve(handle string) ([]byte, error) {
	original, ok := e.originals[handle]
	if !ok {
		return nil, fmt.Errorf("unknown handle")
	}
	return []byte(original), nil
}
func (e *storeEngine) RetrieveQuery(handle, query string) ([]byte, error) {
	original, err := e.Retrieve(handle)
	if err != nil {
		return nil, err
	}
	if strings.TrimSpace(query) == "" {
		e.fullCalls++
		return original, nil
	}
	e.narrowed++
	// Stand in for BM25 narrowing: return only the matching lines' records.
	var kept []string
	for _, line := range strings.Split(string(original), "\n") {
		if strings.Contains(line, query) {
			kept = append(kept, line)
		}
	}
	if len(kept) == 0 {
		return original, nil
	}
	return []byte(strings.Join(kept, "\n")), nil
}
func (e *storeEngine) Stats() (ccr.Stats, error)            { return ccr.Stats{}, nil }
func (e *storeEngine) EncodeTOON(in []byte) ([]byte, error) { return in, nil }
func (e *storeEngine) DecodeTOON(in []byte) ([]byte, error) { return in, nil }

func newStoreEngine() *storeEngine {
	var b strings.Builder
	for i := 0; i < 40; i++ {
		fmt.Fprintf(&b, "dlv-%04d status=delivered endpoint=alpha\n", 2000+i)
	}
	return &storeEngine{originals: map[string]string{"ccr_page1": b.String(), "ccr_page2": "other content\nsecond line\n"}}
}

func retrieveArgs(handle, query string) json.RawMessage {
	raw, _ := json.Marshal(map[string]string{"recovery_handle": handle, "query": query})
	return raw
}

func resultText(t *testing.T, r ToolResult) string {
	t.Helper()
	raw, err := json.Marshal(r)
	if err != nil {
		t.Fatal(err)
	}
	return string(raw)
}

// TestRepeatedRetrieveIsAnsweredWithAPointer covers rule 1: an identical
// (handle, query) is never re-sent, because the bytes are verbatim above.
func TestRepeatedRetrieveIsAnsweredWithAPointer(t *testing.T) {
	eng := newStoreEngine()
	session := newRetrieveSession()

	first := resultText(t, retrieveTool(eng, session, retrieveArgs("ccr_page1", "dlv-2007")))
	if !strings.Contains(first, "dlv-2007") {
		t.Fatalf("the first retrieve must return content: %s", first)
	}
	second := resultText(t, retrieveTool(eng, session, retrieveArgs("ccr_page1", "dlv-2007")))
	if !strings.Contains(second, "already answered earlier in this session") {
		t.Fatalf("the repeat must return the pointer note: %s", second)
	}
	if strings.Contains(second, "endpoint=alpha") {
		t.Fatalf("the repeat must not re-send the content: %s", second)
	}
	// Whitespace-only differences are the same request, not a new one.
	padded := resultText(t, retrieveTool(eng, session, retrieveArgs("ccr_page1", "  dlv-2007  ")))
	if !strings.Contains(padded, "already answered earlier in this session") {
		t.Fatalf("a whitespace-padded repeat is still a repeat: %s", padded)
	}
	// A DIFFERENT query on the same handle is new content and must be served.
	fresh := resultText(t, retrieveTool(eng, session, retrieveArgs("ccr_page1", "dlv-2011")))
	if !strings.Contains(fresh, "dlv-2011") {
		t.Fatalf("a new query must still be answered: %s", fresh)
	}
}

// TestRetrieveStormPaysOutInFull covers rule 2: past the threshold the next
// retrieve returns the whole stored original and says so.
func TestRetrieveStormPaysOutInFull(t *testing.T) {
	eng := newStoreEngine()
	session := newRetrieveSession()

	for i := 0; i < retrieveStormThreshold; i++ {
		out := resultText(t, retrieveTool(eng, session, retrieveArgs("ccr_page1", fmt.Sprintf("dlv-%04d", 2000+i))))
		if strings.Contains(out, "COMPLETE stored original") {
			t.Fatalf("payout came early, at retrieve %d: %s", i+1, out)
		}
	}
	if eng.fullCalls != 0 {
		t.Fatalf("no full recovery should have happened yet, got %d", eng.fullCalls)
	}

	storm := resultText(t, retrieveTool(eng, session, retrieveArgs("ccr_page1", "dlv-2030")))
	if !strings.Contains(storm, "COMPLETE stored original") {
		t.Fatalf("the retrieve past the threshold must pay out in full: %s", storm)
	}
	if eng.fullCalls != 1 {
		t.Fatalf("the payout must be an unfiltered recovery, got %d full calls", eng.fullCalls)
	}
	for _, id := range []string{"dlv-2000", "dlv-2020", "dlv-2039"} {
		if !strings.Contains(storm, id) {
			t.Fatalf("the payout is missing %s, so it is not the full original: %s", id, storm)
		}
	}
	// Having paid out in full, the same handle's full content is now "already
	// served" and a repeat of it points back rather than re-sending.
	again := resultText(t, retrieveTool(eng, session, retrieveArgs("ccr_page1", "")))
	if !strings.Contains(again, "already answered earlier in this session") {
		t.Fatalf("the full original was already given; a repeat must point back: %s", again)
	}
}

// TestRetrieveWithoutASessionBehavesAsBefore is the stateless-safety contract: a
// caller with no session concept keeps the old semantics exactly.
func TestRetrieveWithoutASessionBehavesAsBefore(t *testing.T) {
	eng := newStoreEngine()
	for i := 0; i < retrieveStormThreshold+3; i++ {
		out := resultText(t, retrieveTool(eng, nil, retrieveArgs("ccr_page1", "dlv-2007")))
		if !strings.Contains(out, "dlv-2007") {
			t.Fatalf("retrieve %d returned no content: %s", i+1, out)
		}
		if strings.Contains(out, "caveman: this") {
			t.Fatalf("a session-less retrieve must never emit an anti-storm note: %s", out)
		}
	}
}

// TestAntiStormNeverWithholdsUnseenContent is the honesty gate. The pointer note
// may only ever stand in for bytes this session has already been given.
func TestAntiStormNeverWithholdsUnseenContent(t *testing.T) {
	eng := newStoreEngine()
	session := newRetrieveSession()
	for i := 0; i < retrieveStormThreshold+5; i++ {
		handle, query := "ccr_page1", fmt.Sprintf("dlv-%04d", 2000+i)
		out := resultText(t, retrieveTool(eng, session, retrieveArgs(handle, query)))
		if !strings.Contains(out, "already answered earlier in this session") {
			continue
		}
		t.Fatalf("retrieve %d (%s) was refused but never served: %s", i+1, query, out)
	}
	// A never-requested handle is always served, whatever the session count.
	out := resultText(t, retrieveTool(eng, session, retrieveArgs("ccr_page2", "second")))
	if strings.Contains(out, "already answered") || !strings.Contains(out, "second line") {
		t.Fatalf("an unseen handle must always be served: %s", out)
	}
}

